"""Server-side connection factories for the JSI protocol.

This module contains adapters that need to be aplied on top of the
:class:`jsilib.transport.ITransportAcceptor` interface in order to translate
from low-level transport layer into a high-level JSI protocol layer.
"""

import logging
import typing

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.aio.interface import IReactor
from jsilib.transport.interface import ITransportAcceptor

from . import _globals
from . import exc as jsi_exc
from .connection import JSIConnection, JSISwimConnection
from .interface import IJSIAcceptor, IJSIConnection
from .settings import Settings

__all__ = export = _utils.ExportList()

logger = logging.getLogger(_globals.LOGGER_NAME)


@export
class JSIAcceptor(IJSIAcceptor):
    """A default adapter that translates lower-level
    :class:`ITransportAcceptor` interface into a higher-level
    :class:`IJSIAcceptor` interface.

    :param reactor:
        Reactor to be used.

    :param target:
        Target transport-layer acceptor.

    :param settings:
        Settings for the JSI protocol.
    """

    def __init__(self,
                 reactor: IReactor,
                 target: ITransportAcceptor,
                 settings: Settings = Settings(),
                 jsi_connection_cls: typing.Type[IJSIConnection] = JSIConnection):

        @_utils.log_exceptions(logger)
        async def accept_loop():
            while not target.is_closed():
                transport_connection = await target.accept()
                jsi_connection = jsi_connection_cls(reactor, transport_connection, settings)
                self._forwarder.dispatch(jsi_connection)

        self._forwarder = ForwardingJSIAcceptor()
        self._accept_loop_task = reactor.run(accept_loop())

    def is_closed(self) -> bool:
        return self._forwarder.is_closed()

    async def close(self):
        if not self.is_closed():
            await self._forwarder.close()
            await self._accept_loop_task.cancel()

    async def accept(self) -> IJSIConnection:
        connection = await self._forwarder.accept()
        logger.debug('[%s] Connection accepted (%s)', _utils.get_obj_addr(self), _utils.get_obj_addr(connection))
        return connection


@export
class JSISwimAcceptor(IJSIAcceptor):
    """JSI acceptor with SWIM-compatible mode enabled."""

    def __init__(self,
                 reactor: IReactor,
                 target: ITransportAcceptor,
                 settings: Settings = Settings()):
        self._reactor = reactor
        self._target = target
        self._settings = settings
        self._closed = False

    async def accept(self) -> IJSIConnection:
        if self._closed:
            raise jsi_exc.AcceptorClosedError(self)
        transport_connection = await self._target.accept()
        return JSISwimConnection(self._reactor, transport_connection, self._settings)

    async def close(self):
        self._closed = True

    def is_closed(self) -> bool:
        return self._closed


@export
class ForwardingJSIAcceptor(IJSIAcceptor):
    """An acceptor that simply allows to accept a "forwarded" JSI connection.

    This is mostly usable for testing of the upper-layer purposes, when it is
    need to force server to accept a known connection object.

    :param reactor:
        Reactor to be used.
    """
    _close_signal = object()

    def __init__(self):
        self._queue: asyncio.Queue[IJSIConnection] = asyncio.Queue()
        self._closed = False

    def dispatch(self, connection: IJSIConnection):
        self._queue.put_nowait(connection)

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            self._queue.put_nowait(self._close_signal)

    async def accept(self) -> IJSIConnection:
        connection = await self._queue.get()
        if connection is self._close_signal:
            raise jsi_exc.AcceptorClosedError(self)
        return connection
